package com.smartgrocery.controller; import com.smartgrocery.entity.Product; import com.smartgrocery.repository.ProductRepository; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/products") public class ProductController { private final ProductRepository repo; public ProductController(ProductRepository r){repo=r;} @GetMapping public List<Product> all(@RequestParam(defaultValue="") String search){return repo.findByActiveTrueAndNameContainingIgnoreCase(search);} @GetMapping("/{id}") public Product one(@PathVariable Long id){return repo.findById(id).orElseThrow();} @PostMapping public Product create(@RequestBody Product p){return repo.save(p);} @PutMapping("/{id}") public Product update(@PathVariable Long id,@RequestBody Product p){Product x=repo.findById(id).orElseThrow();x.setName(p.getName());x.setCategory(p.getCategory());x.setPrice(p.getPrice());x.setUnit(p.getUnit());return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }